var t=[{title:`Volwassenen van 18–64 jaar`,text:`De richtlijn van de Wereldgezondheidsorganisatie beveelt 150–300 minuten aerobe activiteit met matige intensiteit per week aan, of 75–150 minuten intensieve activiteit, of een gelijkwaardige combinatie van beide. Ook wordt spierversterkende activiteit voor alle grote spiergroepen op minstens twee dagen per week aanbevolen. Meer activiteit kan extra voordelen geven, maar de juiste hoeveelheid hangt af van je gezondheid en belastbaarheid.`},{title:`Wat intensiteit betekent`,text:`Matige activiteit verhoogt je ademhaling en hartslag, maar je kunt nog een gesprek voeren. Bij intensieve activiteit kun je moeilijk in volzinnen praten. Stevig wandelen of rustig fietsen telt als matig, en rennen of hard fietsen telt als intensief. Je kunt de minuten over de week verdelen in sessies die in je agenda passen, dus één lange training is niet nodig.`},{title:`Ouderen en jongeren`,text:`Ouderen volgen dezelfde aerobe en krachtdoelen. Ze worden ook aangemoedigd om, waar mogelijk, op minstens drie dagen per week gevarieerde activiteit te doen met nadruk op balans en kracht. Voor 5–17 jaar beveelt de WHO gemiddeld minstens 60 minuten matige tot intensieve activiteit per dag aan, verspreid over de week, met intensieve activiteit en spier- en botversterkende activiteit op minstens drie dagen per week.`},{title:`Klein beginnen telt ook`,text:`Elke toename ten opzichte van inactiviteit helpt. Wandelingen van tien minuten, de trap nemen en korte sessies thuis bouwen allemaal op naar de aanbevolen totalen. Minder zitten helpt ook als je al sport, en lichte activiteit kan een deel van die zittijd vervangen.`},{title:`Voorbeeld`,text:`Een beginner kan twee full-body-trainingen en drie wandelingen van 30 minuten plannen en de wandelingen dan langzaam verlengen richting het aerobe doel. Houd wandelminuten apart bij van krachtsets. De richtlijnen zijn doelen voor hele bevolkingsgroepen, dus je hoeft niet meteen naar de volledige hoeveelheid te springen.`}];var i=[{label:`WHO-richtlijnen 2020`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9219310/`},{label:`CDC-beweegrichtlijnen`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};